import React from "react";
import { useNavigate, useParams } from "react-router-dom";
import "./JobDetails.css";

const jobData = {
  1: {
    title: "Frontend Developer",
    details: "Full job description with responsibilities, skills, benefits, and salary.",
  },
  2: {
    title: "Backend Engineer",
    details: "Detailed job description for backend engineer role.",
  },
};

export default function JobDetails() {
  const { id } = useParams();
  const navigate = useNavigate();
  const job = jobData[id];

  return (
    <div className="job-details-container">
      <h2>{job.title}</h2>
      <p>{job.details}</p>
      <button onClick={() => navigate(`/apply/${id}`)} className="apply-btn">
        Apply Now
      </button>
    </div>
  );
}
